const tasks = await query('com.example.type.task');
const matches = tasks.filter(t => /docs/i.test(t.title || ''));
for (const t of matches) update(t, (o) => { o.status = 'done'; });
await flush();
const after = await query('com.example.type.task');
print('updated:', matches.map(t => t.title).join(', '));
print('done total:', after.filter(t => t.status === 'done').length);
for (const t of after) print(JSON.stringify({title: t.title, status: t.status}));

